import Foundation

extension PluginComponentBuild {
    /// Each capability `name: func(input: name-input) -> string` calls the
    /// package's `func name(field: String, list: [String]) -> String`, with
    /// kebab-case names in lower camel case.
    static func bindings(_ capabilities: [(name: String, fields: [ShellField])]) -> String {
        var lines = [
            "// Generated by `cove plugin build` from capabilities.wit. Do not edit.",
            "import CovePluginKit",
        ]
        for capability in capabilities {
            let function = camelCase(capability.name)
            let parameters = capability.fields.enumerated().map { index, _ in
                "_ p\(index): UnsafeRawPointer?, _ n\(index): Int"
            }.joined(separator: ", ")
            let arguments = capability.fields.enumerated().map { index, field in
                "\(camelCase(field.name)): CanonicalABI.\(field.isList ? "strings" : "string")(p\(index), n\(index))"
            }.joined(separator: ", ")
            let symbol = "cove_export_" + capability.name.replacingOccurrences(of: "-", with: "_")
            lines += [
                "",
                "@_expose(wasm, \"\(capability.name)\")",
                "@_cdecl(\"\(symbol)\")",
                "func \(symbol)(\(parameters)) -> UnsafeMutableRawPointer {",
                "    CanonicalABI.result(\(function)(\(arguments)))",
                "}",
            ]
        }
        return lines.joined(separator: "\n") + "\n"
    }

    private static func camelCase(_ name: String) -> String {
        let words = name.split(separator: "-")
        return words.enumerated().map { index, word in
            index == 0 ? String(word) : word.prefix(1).uppercased() + word.dropFirst()
        }.joined()
    }
}
